INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22101, 'Matthew 4:7', 'Matthew', 4, 7, '&nbsp;عيسىٰ جواب ورکړو چې، ”صحيفې دا هم وائى چې، تاسو په خپل مالِک خُدائ پاک آزمېښت مۀ کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22102, 'Matthew 4:8', 'Matthew', 4, 8, '&nbsp;بيا اِبليس هغه د يو ډېر اوچت غرۀ څوکې ته وخېژولو او د دُنيا ټولې بادشاهۍ او د هغې شان او شوکت يې ورښکاره کړل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22103, 'Matthew 4:9', 'Matthew', 4, 9, '&nbsp;او ورته يې ووئيل چې، ”دا هر څۀ به تا له درکړم خو کۀ تۀ راته صرف سجده وکړې او زما عبادت وکړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22104, 'Matthew 4:10', 'Matthew', 4, 10, '&nbsp;خو عيسىٰ ورته وفرمائيل چې، ”ورک شه اِبليسه. صحيفې وائى چې، تۀ تش مالِک خُدائ پاک ته سجده کوه او صرف هم د هغۀ عبادت کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22105, 'Matthew 4:11', 'Matthew', 4, 11, '&nbsp;نو اِبليس هغه پرېښودو او فرښتې راغلې او د هغۀ په خِدمت کښې حاضرې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22106, 'Matthew 4:12', 'Matthew', 4, 12, '&nbsp;هرکله چې عيسىٰ واورېدل چې يحيىٰ ګرفتار شوے دے نو هغه ګليل ته واپس راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22107, 'Matthew 4:13', 'Matthew', 4, 13, '&nbsp;ناصرت يې پرېښودو او په کفرنحُوم ښاريې کښې ډېره شو چې د درياب په غاړه دے چې د زبولون او نفتالى په سرحد کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22108, 'Matthew 4:14', 'Matthew', 4, 14, '&nbsp;دا د يشعياه نبى خبرې پوره کول وُو يعنې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22109, 'Matthew 4:15', 'Matthew', 4, 15, '&nbsp;”د زبولون او د نفتالى علاقه، د درياب طرف ته د اُردن نه په خوا کښې، د غېر‌يهوديانو ګليل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22110, 'Matthew 4:16', 'Matthew', 4, 16, '&nbsp;کوم خلق چې په تيارۀ کښې ناست وُو، هغوئ يوه لويه رڼا وليدله، او څوک چې په زمکه د مرګ په سورى کښې ناست وُو، پرې رڼا وځلېده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22111, 'Matthew 4:17', 'Matthew', 4, 17, '&nbsp;د هغې ورځې نه عيسىٰ دا بيان شروع کړو چې، ”توبه ګار شئ ځکه چې د خُدائ پاک بادشاهى ستاسو مينځ ته راغلې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22112, 'Matthew 4:18', 'Matthew', 4, 18, '&nbsp;عيسىٰ د ګليل درياب په غاړه ګرځېدو چې دوه وروڼه يې وليدل، يو شمعون چې د پطروس په نوم ياديږى او د هغۀ ورور اندرياس. هغوئ په درياب کښې جال اچولو ځکه چې هغوئ ماهيګر وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22113, 'Matthew 4:19', 'Matthew', 4, 19, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”ما پسې راځئ او زۀ به تاسو آدم‌ګير جوړ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22114, 'Matthew 4:20', 'Matthew', 4, 20, '&nbsp;هغوئ سمدستى خپل جالونه پرېښودل او په هغۀ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22115, 'Matthew 4:21', 'Matthew', 4, 21, '&nbsp;کله چې عيسىٰ د دې ځائ نه وړاندې لاړو نو دوه وروڼه يې وليدل، يعقوب د زبدى زوئ او د هغۀ ورور يوحنا چې په کشتۍ کښې يې د خپل پلار زبدى سره جالونه مرمت کول. هغوئ يې راوبلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22116, 'Matthew 4:22', 'Matthew', 4, 22, '&nbsp;هغوئ سمدستى کشتۍ او خپل پلار پرېښودل او په هغۀ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22117, 'Matthew 4:23', 'Matthew', 4, 23, '&nbsp;عيسىٰ په ټول ګليل کښې ګرځېدو، د يهوديانو په عبادتخانو کښې يې تعليم ورکولو او د خُدائ پاک د بادشاهۍ د زيرى بيان يې کولو او د خلقو هر رنځ او بيمارى يې روغوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22118, 'Matthew 4:24', 'Matthew', 4, 24, '&nbsp;د هغۀ آوازه په ټول شام کښې خوره شوه او د هر رنځ بيماران چې په عذاب آخته وُو، يعنې هغوئ چې پيريانو نيولى وُو، ميرګو نيولى او شل يې ورله راوستل نو هغۀ روغ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22119, 'Matthew 4:25', 'Matthew', 4, 25, '&nbsp;ډېر خلق ورپسې روان شول چې د ګليل، د دِکپولس، د يروشلم، د يهوديه او د اُردن د پورې غاړې اوسېدونکى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22120, 'Matthew 5:1', 'Matthew', 5, 1, '&nbsp;کله چې عيسىٰ ګڼ خلق وليدل نو غرۀ ته وختلو او هلته کښېناستو. او کله چې د هغۀ مريدان ورته راټول شول،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22121, 'Matthew 5:2', 'Matthew', 5, 2, '&nbsp;نو هغۀ ورته داسې تعليم شروع کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22122, 'Matthew 5:3', 'Matthew', 5, 3, '&nbsp;”بختور دى هغوئ چې د روح غريبان دى ځکه چې د آسمان بادشاهى د هغوئ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22123, 'Matthew 5:4', 'Matthew', 5, 4, '&nbsp;بختور دى هغوئ چې غمژن دى، هغوئ به تسلى ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22124, 'Matthew 5:5', 'Matthew', 5, 5, '&nbsp;بختور دى هغوئ چې حليمان دى ځکه چې دوئ به د زمکې وارثان شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22125, 'Matthew 5:6', 'Matthew', 5, 6, '&nbsp;بختور دى هغوئ چې د صداقت اوږى تږى دى، دوئ به ماړۀ کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22126, 'Matthew 5:7', 'Matthew', 5, 7, '&nbsp;بختور دى هغوئ چې رحم کوى، په هغوئ به رحم وکړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22127, 'Matthew 5:8', 'Matthew', 5, 8, '&nbsp;بختور دى هغوئ چې زړونه يې پاک دى، هغوئ به د خُدائ پاک ديدن وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22128, 'Matthew 5:9', 'Matthew', 5, 9, '&nbsp;بختور دى د امن راوستونکى، خُدائ پاک به هغوئ ته خپل زامن ووائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22129, 'Matthew 5:10', 'Matthew', 5, 10, '&nbsp;بختور دى هغوئ چې د خُدائ پاک د رضا پوره کولو دپاره زورَولے کيږى، د آسمان بادشاهى د هغوئ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22130, 'Matthew 5:11', 'Matthew', 5, 11, '&nbsp;تاسو بختور يئ کله چې خلق درته سپکې سپورې وائى، او زوروى مو او زما له وجې خلق ستاسو په حقله هر قِسم دروغژنې بدې خبرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22131, 'Matthew 5:12', 'Matthew', 5, 12, '&nbsp;دا هر څۀ تاسو په خوشحالۍ او روڼ تندى وزغمئ ځکه چې په آسمان کښې ستاسو دپاره لوئ اجر دے، ځکه چې ستاسو نه وړاندې هم دغه رنګ دوئ نبيان وزورول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22132, 'Matthew 5:13', 'Matthew', 5, 13, '&nbsp;تاسو د دُنيا دپاره مالګه يئ. کۀ مالګه بې‌خونده شى، نو بيا به څنګه مالګينه شى؟ دا بيا د هيڅ څيز دپاره په کار نۀ راځى او بهر وغورزولے شى او د پښو لاندې کولو جوګه شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22133, 'Matthew 5:14', 'Matthew', 5, 14, '&nbsp;تاسو د ټولې دُنيا دپاره رڼا يئ. کوم ښار چې په غرۀ آباد وى هغه پټېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22134, 'Matthew 5:15', 'Matthew', 5, 15, '&nbsp;چې ډيوه بله شى نو څوک پرې لوښے نۀ ږدى، بلکې د ډيوټ دپاسه کېښودلے شى چرته چې د کور ټولو خلقو ته رڼا ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22135, 'Matthew 5:16', 'Matthew', 5, 16, '&nbsp;او تاسو هم دغه رنګ د خلقو د وړاندې رڼا خوره کړئ د دې دپاره چې هرکله هغوئ ستاسو ښۀ کارونه ووينى نو هغوئ به ستاسو د آسمانى پلار، لوئى بيان کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22136, 'Matthew 5:17', 'Matthew', 5, 17, '&nbsp;دا خيال مۀ کوئ چې ګنې زۀ د دې دپاره راغلے يم چې شريعت او د نبيانو کتابونه منسوخ کړم. زۀ د هغوئ منسوخ کولو له نۀ يم راغلے بلکې پوره کولو له راغلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22137, 'Matthew 5:18', 'Matthew', 5, 18, '&nbsp;زۀ تاسو ته رښتيا وايم، ترڅو پورې چې آسمان او زمکه ختم شوى نۀ وى نو د شريعت يو حرف يا د حرف نه يو زبر قدرې به ختم نۀ شى، ترڅو چې دا هر څۀ سر ته رسېدلى نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22138, 'Matthew 5:19', 'Matthew', 5, 19, '&nbsp;نو کۀ څوک ورنه د شريعت يوه ذره شان هم مات کړى او نورو خلقو ته د داسې کولو تعليم ورکړى نو د آسمان په بادشاهۍ کښې به د دوئ ځائ د ټولو نه لاندې وى. خو هغه څوک چې په شريعت عمل وکړى او نورو ته يې تعليم هم ورکوى، هغه به د آسمان په بادشاهۍ کښې لوئى بيامومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22139, 'Matthew 5:20', 'Matthew', 5, 20, '&nbsp;زۀ تاسو ته دا وايم، ترڅو چې تاسو په صداقت کولو کښې د فريسيانو او د شرعې د عالمانو نه زيات نۀ يئ نو تاسو بيا هيڅکله هم د آسمان په بادشاهۍ کښې داخلېدے نۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22140, 'Matthew 5:21', 'Matthew', 5, 21, '&nbsp;تاسو اورېدلى دى چې زمونږ پلار نيکۀ ته وئيلے شوى وُو چې، قتل مۀ کوئ. هغه څوک چې قتل وکړى هغۀ ته به ضرور په عدالت کښې سزا ورکولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22141, 'Matthew 5:22', 'Matthew', 5, 22, '&nbsp;خو زۀ تاسو ته دا وايم چې هر څوک چې يو ورور ته غصه هم وکړى، هغۀ ته به په عدالت کښې ضرور سزا ورکړے شى. او کۀ هغه ورته کم عقل ووائى نو هغه به ضرور عدالت ته جواب ورکوى، او کۀ چرې ورته ليونے ووائى نو هغۀ ته به د دوزخ د اور خطره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22142, 'Matthew 5:23', 'Matthew', 5, 23, '&nbsp;کۀ چرې تاسو د قربانۍ ځائ ته کوم څيز راوړئ او په دې وخت کښې درته راياد شى چې ستا ورور په څۀ خبره درنه خفه دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22143, 'Matthew 5:24', 'Matthew', 5, 24, '&nbsp;نو خپله قربانى په هغه ځائ پرېږده. لاړ شه، اول خپل ورور رضا کړه او بيا راشه او خپل نذر وړاندې کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22144, 'Matthew 5:25', 'Matthew', 5, 25, '&nbsp;کۀ د چا سره ستا مقدمه وى نو زر ورسره روغه جوړه وکړه، کله چې ورسره عدالت ته په لاره روان يې. هسې نه چې هغه دې قاضى ته پېش کړى او قاضى سپاهى ته، او تۀ قېد شې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22145, 'Matthew 5:26', 'Matthew', 5, 26, '&nbsp;زۀ تاسو ته دا وايم چې تاسو به تر هغې آزاد نۀ شئ ترڅو چې مو خپله جرمانه پېسه پېسه ادا کړې نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22146, 'Matthew 5:27', 'Matthew', 5, 27, '&nbsp;تاسو اورېدلى وُو چې هغوئ ته وئيلے شوى وُو چې، زنا مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22147, 'Matthew 5:28', 'Matthew', 5, 28, '&nbsp;خو زۀ تاسو ته دا وايم چې کۀ يو سړے يوې ښځې ته په بد نيت سره وګورى نو هغۀ په خپل زړۀ کښې د هغې سره زنا کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22148, 'Matthew 5:29', 'Matthew', 5, 29, '&nbsp;کۀ چرې ستا ښۍ سترګه تا ګناه ته ولمسوى نو وې باسه او وې وغورزوه. ستا دپاره به دا ښۀ وى چې د خپل وجود يو اندام بائيلې، نه چې ستا ټول وجود دوزخ ته وغورزولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22149, 'Matthew 5:30', 'Matthew', 5, 30, '&nbsp;او کۀ چرې ستا ښے لاس د ګناه سبب شى نو پرې يې کړه او وې غورزوه. ستا دپاره دا بهتره ده چې د خپل وجود يو اندام بائيلې، نۀ دا چې ستا ټول وجود دوزخ ته لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22150, 'Matthew 5:31', 'Matthew', 5, 31, '&nbsp;هغوئ ته وئيلے شوى وُو، کوم سړے چې خپله ښځه طلاقه کړى نو ضرور دې هغې له طلاق نامه ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22151, 'Matthew 5:32', 'Matthew', 5, 32, '&nbsp;خو زۀ درته دا وايم چې کوم سړے چې د زناکارۍ د جرم نه په بله څۀ وجه خپله ښځه طلاقه کړى نو په هغې باندې زنا کوى، او هر څوک چې طلاقې شوې ښځې سره وادۀ وکړى هغه زنا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22152, 'Matthew 5:33', 'Matthew', 5, 33, '&nbsp;بيا به تاسو دا اورېدلى وى چې زمونږ پلار نيکۀ ته وئيلے شوى وُو چې، خپل قسم مۀ ماتوئ خو خپل قسم د مالِک خُدائ دپاره ضرور پوره کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22153, 'Matthew 5:34', 'Matthew', 5, 34, '&nbsp;خو زۀ تاسو ته دا وايم چې هيڅکله هم قسم مۀ خورئ، نۀ په آسمان، ځکه چې دا د خُدائ پاک تخت دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22154, 'Matthew 5:35', 'Matthew', 5, 35, '&nbsp;او نۀ په زمکه ځکه چې دا د هغۀ د پښو چوکۍ ده، او نۀ په يروشلم ځکه چې دا د لوئ بادشاه ښار دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22155, 'Matthew 5:36', 'Matthew', 5, 36, '&nbsp;او نۀ په خپل سر ځکه چې تۀ د دې يو وېښتۀ هم په خپله مرضۍ نۀ سپينولے او نۀ تورولے شې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22156, 'Matthew 5:37', 'Matthew', 5, 37, '&nbsp;تاسو يواځې د ”آو“ په ځائ ”آو،“ او د ”نه“ په ځائ ”نه“ جواب ورکوئ. د دې نه زيات چې دے هغه د اِبليس کار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22157, 'Matthew 5:38', 'Matthew', 5, 38, '&nbsp;تاسو خبر يئ چې دا وئيلے شوى وُو چې، د سترګې په بدل کښې سترګه او د غاښ په بدل کښې غاښ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22158, 'Matthew 5:39', 'Matthew', 5, 39, '&nbsp;خو زۀ تاسو ته دا وايم چې د هغه سړى خلاف مۀ ودرېږئ څوک چې درسره بد کوى. کۀ څوک درله په ښى مخ څپېړه درکړى نو ګس مخ هم ورواړوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22159, 'Matthew 5:40', 'Matthew', 5, 40, '&nbsp;کۀ چرې يو سړے ستا په قميص دعوىٰ وکړى نو تۀ خپل کوټ هم ورله ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22160, 'Matthew 5:41', 'Matthew', 5, 41, '&nbsp;کۀ چرې يو اختيار لرونکے تا يو ميل په بيګار بوځى نو تۀ ورسره دوه ميله لاړ شه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22161, 'Matthew 5:42', 'Matthew', 5, 42, '&nbsp;چې څوک درنه څۀ وغواړى هغه ورکړه او د داسې سړى نه مخ مۀ اړوه څوک چې درنه قرض غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22162, 'Matthew 5:43', 'Matthew', 5, 43, '&nbsp;تاسو خبر يئ چې وئيلے شوى وُو چې، د خپل ګاونډى سره مينه ساتئ او د خپل دشمن نه کرکه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22163, 'Matthew 5:44', 'Matthew', 5, 44, '&nbsp;خو زۀ درته دا وايم چې د خپلو دشمنانو سره مينه کوئ، او څوک چې تاسو زوروى د هغوئ دپاره دُعا کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22164, 'Matthew 5:45', 'Matthew', 5, 45, '&nbsp;چې په دې تاسو د خپل آسمانى پلار زامن شئ، څوک چې په بدو او په ښو يو شان نمر راخېژوى او په نېکو او بدو خلقو يو شان باران ورَوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22165, 'Matthew 5:46', 'Matthew', 5, 46, '&nbsp;کۀ تاسو صرف د هغوئ سره مينه کوئ څوک چې تاسو سره مينه کوى نو بيا تاسو د کوم اجر اُميدوار يئ؟ ولې محصولچيان دغه شان نۀ کوى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22166, 'Matthew 5:47', 'Matthew', 5, 47, '&nbsp;کۀ چرې تاسو يواځې په خپلو وروڼو سلام اچوئ نو دا کومه نا آشنا خبره ده؟ دغه څۀ خو بې‌دينه هم کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22167, 'Matthew 5:48', 'Matthew', 5, 48, '&nbsp;تاسو کامِل شئ لکه څنګه چې ستاسو آسمانى پلار کامِل دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22168, 'Matthew 6:1', 'Matthew', 6, 1, '&nbsp;”خبردار چې د خپلې پرهيزګارۍ ښودنه د خلقو په مخکښې ونۀ کړئ. کۀ تاسو داسې وکړئ نو د آسمانى پلار سره ستاسو دپاره هيڅ اجر نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22169, 'Matthew 6:2', 'Matthew', 6, 2, '&nbsp;هرکله چې تاسو څۀ خېرات کوئ نو په بيګل يې مۀ ډنډوره کوئ، لکه څنګه چې يې رياکاران په عبادتخانو او کوڅو کښې کوى چې خلق يې صِفت وکړى. زۀ تاسو ته رښتيا وايم چې هغوئ ته اجر پوره مِلاو شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22170, 'Matthew 6:3', 'Matthew', 6, 3, '&nbsp;خو تاسو چې کله هم خېرات کوئ نو په داسې يې کوئ چې ګس لاس مو په دې خبر نۀ شى چې ستاسو ښے لاس څۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22171, 'Matthew 6:4', 'Matthew', 6, 4, '&nbsp;ستاسو خېرات دې ضرور په پړده کښې وى نو ستاسو آسمانى پلار چې دا هر څۀ وينى چې تاسو يې په پړده کښې کوئ، هغه به د دې بدل درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22172, 'Matthew 6:5', 'Matthew', 6, 5, '&nbsp;بيا دا چې تاسو کله هم دُعا کوئ نو د رياکارانو په شان مۀ جوړېږئ. هغوئ دا ډېر خوښوى چې په عبادتخانو او چوکونو کښې د دُعا دپاره ودريږى چې هر څوک يې ووينى. زۀ تاسو ته رښتيا وايم چې هغوئ ته خپل اجر پوره مِلاو شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22173, 'Matthew 6:6', 'Matthew', 6, 6, '&nbsp;خو کله چې تاسو دُعا کوئ نو خپلې کوټې ته ننوځئ، ور پورې کړئ او خپل پلار ته په زارو شئ، څوک چې د پړدې په دغه ځائ کښې موجود دے. او ستاسو آسمانى پلار څوک چې پټ رازونه وينى، هغه به بدل درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22174, 'Matthew 6:7', 'Matthew', 6, 7, '&nbsp;او کله چې تاسو دُعا کوئ نو په دُعا کښې د بې‌دينه قومونو په شان د بې‌مطلبه خبرو تکرار مۀ کوئ، د چا چې دا خيال وى چې د ډېرو وئيلو په وجه به د هغوئ واورېدے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22175, 'Matthew 6:8', 'Matthew', 6, 8, '&nbsp;د هغوئ پېښې مۀ کوئ، ستاسو آسمانى پلار ستاسو د غوښتو نه وړاندې ستاسو په حاجتونو خبر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22176, 'Matthew 6:9', 'Matthew', 6, 9, '&nbsp;نو داسې دُعا کوئ، اے په آسمان کښې زمونږ پلاره، ستا نوم دې پاک وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22177, 'Matthew 6:10', 'Matthew', 6, 10, '&nbsp;ستا بادشاهى دې راشى، ستا مرضى دې په زمکه هم پوره شى څنګه چې په آسمان کښې پوره کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22178, 'Matthew 6:11', 'Matthew', 6, 11, '&nbsp;مونږ له خپل روزمره رزق راکړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22179, 'Matthew 6:12', 'Matthew', 6, 12, '&nbsp;او زمونږ ګناهونه معاف کړه، لکه څنګه چې مونږ خپل قصوروار معاف کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22180, 'Matthew 6:13', 'Matthew', 6, 13, '&nbsp;او مونږ په آزمېښت کښې مۀ اچوه، خو مونږ د بدۍ نه بچ کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22181, 'Matthew 6:14', 'Matthew', 6, 14, '&nbsp;ځکه کۀ تاسو د نورو نافرمانى معاف کړئ، نو ستاسو آسمانى پلار به هم تاسو معاف کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22182, 'Matthew 6:15', 'Matthew', 6, 15, '&nbsp;خو کۀ تاسو نور نۀ معاف کوئ نو ستاسو آسمانى پلار به هم ستاسو نافرمانى معاف نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22183, 'Matthew 6:16', 'Matthew', 6, 16, '&nbsp;هر کله چې تاسو روژه نيسئ نو د رياکارانو په شان ځانونه خفه مۀ ښکاره کوئ. هغوئ خپل مخونه ځکه ورانوى چې خلق ووائى چې ګنې د دوئ روژه ده. زۀ تاسو ته رښتيا وايم چې هغوئ ته خپل اجر پوره مِلاو شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22184, 'Matthew 6:17', 'Matthew', 6, 17, '&nbsp;خو هر کله چې روژه نيسئ نو خپل سر غوړوئ او مخ وينځئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22185, 'Matthew 6:18', 'Matthew', 6, 18, '&nbsp;د دې دپاره چې څوک دا ونۀ وائى چې ګنې ستا روژه ده، خو تش ستا آسمانى پلار څوک چې په پړده کښې دے. او ستا آسمانى پلار چې په رازونو خبر دے، هغه به تا له ستا اجر درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22186, 'Matthew 6:19', 'Matthew', 6, 19, '&nbsp;په زمکه ځان له خزانې مۀ جمع کوئ چرته چې هغه وينۀ وهى او زنګ کيږى او غلۀ ورپسې کنډر کوى او پټوى يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22187, 'Matthew 6:20', 'Matthew', 6, 20, '&nbsp;خو خپل ځان له خزانې په آسمان کښې جمع کوئ چرته چې نۀ وينۀ شته او نۀ زنګ چې دا خرابې کړى، چرته چې نۀ غل کنډر کوى او نۀ يې پټوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22188, 'Matthew 6:21', 'Matthew', 6, 21, '&nbsp;ځکه چې چرته ستا خزانه وى هلته به ستا زړۀ هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22189, 'Matthew 6:22', 'Matthew', 6, 22, '&nbsp;سترګې د بدن دپاره ډيوې دى. کۀ ستا سترګې روغې وى نو ستا ټول بدن به رڼا وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22190, 'Matthew 6:23', 'Matthew', 6, 23, '&nbsp;خو کۀ سترګې دې خرابې وى نو ستا ټول بدن به په توره تيارۀ کښې وى. او کۀ چرې کومه رڼا چې په تا کښې ده، کۀ هغه هم تيارۀ ده نو بيا دا څومره لوئ تورتم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22191, 'Matthew 6:24', 'Matthew', 6, 24, '&nbsp;يو غلام هم د دوو مالِکانو خِدمت نۀ شى کولے. ځکه چې يا خو به هغه د يو نه نفرت کوى او د بل سره مينه، او يا به هغه د يو وفادار وى او د بل نه به کرکه کوى. تاسو د خُدائ پاک او د مال دولت دواړو يو ځائ خِدمت نۀ شئ کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22192, 'Matthew 6:25', 'Matthew', 6, 25, '&nbsp;ځکه زۀ تاسو ته دا وايم چې د خپل ژوندون دپاره دا اندېښنه مۀ کوئ چې څۀ به وخورو، څۀ به وڅښو، او يا څۀ به اغوندو. ولې ژوندون د روټۍ، او بدن د جامو نه ډېر غوره نۀ دے څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22193, 'Matthew 6:26', 'Matthew', 6, 26, '&nbsp;د هوا مارغانو ته وګورئ، دوئ نۀ خو کَرى او نۀ رېبى او نۀ يې خمبو کښې جمع کوى خو بيا هم ستاسو آسمانى پلار هغوئ له رزق ورکوى. نو بيا تاسو هغۀ ته د هغوئ نه ډېر اهم نۀ يئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22194, 'Matthew 6:27', 'Matthew', 6, 27, '&nbsp;په تاسو کښې داسې څوک شته چې هغه په اندېښنو خپل ژوند يو ساعت قدرې زيات کړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22195, 'Matthew 6:28', 'Matthew', 6, 28, '&nbsp;د جامو اندېښنې بيا د څۀ دپاره؟ په پټو کښې ځنګلى ګلونو ته خو لږ خيال وکړئ، چې هغه څنګه راټوکيږى، نۀ خو هغوئ خوارى کوى او نۀ ځان دپاره جامې جوړوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22196, 'Matthew 6:29', 'Matthew', 6, 29, '&nbsp;خو زۀ تاسو ته دا وايم چې سليمان چرې هم سره د خپل ټول شان او شوکت د دې ګلونو په شان ښائسته جامې اچولې نۀ وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22197, 'Matthew 6:30', 'Matthew', 6, 30, '&nbsp;خو کۀ چرې خُدائ پاک د پټو واښو له داسې جامې ورکوى، کوم چې نن شته او سبا به په تنور کښې غورزولے شى، نو ولې هغه به بيا تاسو ته ښکلې جامې در نۀ کړى څۀ؟ اے د کم ايمان خاوندانو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22198, 'Matthew 6:31', 'Matthew', 6, 31, '&nbsp;نو دا اندېښنه مۀ کوئ چې څۀ به وخورو، څۀ به وڅښو يا څۀ به واغوندو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22199, 'Matthew 6:32', 'Matthew', 6, 32, '&nbsp;په دې ټولو څيزونو پسې بې‌دينه زغلى، خو ستاسو آسمانى پلار ستاسو د حاجتونو نه ښۀ خبر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22200, 'Matthew 6:33', 'Matthew', 6, 33, '&nbsp;تاسو د هر څۀ نه اول د خُدائ پاک د بادشاهۍ او د هغۀ د رښتينوالۍ لټون کوئ، نو بيا به هغه دا ټول څيزونه هم تاسو ته درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');